interface PhoneDevice {
    void makeCall(String number);
}

interface CameraDevice {
    void capturePhoto();
}

interface GpsDevice {
    String getCoordinates();
}

class SmartPhone implements PhoneDevice, CameraDevice, GpsDevice {
    private String model;
    public SmartPhone(String model) { this.model = model; }

    @Override
    public void makeCall(String number) {
        System.out.println("[" + model + "] Dialing " + number);
    }

    @Override
    public void capturePhoto() {
        System.out.println("[" + model + "] Click! 48MP photo captured.");
    }

    @Override
    public String getCoordinates() {
        return "37.7749° N, 122.4194° W";
    }
}

public class SmartDemo {
    public static void main(String[] args) {
        SmartPhone pixel = new SmartPhone("Pixel 9");

        // Viewing through Phone lens
        PhoneDevice phone = pixel;
        phone.makeCall("555-0199");

        // Viewing through Camera lens
        CameraDevice cam = pixel;
        cam.capturePhoto();

        // Viewing through GPS lens
        GpsDevice gps = pixel;
        System.out.println("Location: " + gps.getCoordinates());
    }
}

