interface Printable {
    void render();
}

interface ScreenDisplayable {
    void render();
}

class CanvasDocument implements Printable, ScreenDisplayable {
    private String title;
    public CanvasDocument(String title) { this.title = title; }

    // Single implementation satisfies BOTH Printable and ScreenDisplayable!
    @Override
    public void render() {
        System.out.println("Rendering canvas document: '" + title + "' to target surface.");
    }
}

public class RenderDemo {
    public static void main(String[] args) {
        CanvasDocument doc = new CanvasDocument("Architecture Diagram");

        Printable p = doc;
        p.render();

        ScreenDisplayable s = doc;
        s.render();
    }
}

