interface Lifecycle {
    void start();
    void stop();
}

interface Metrizable {
    int getCpuUsage();
}

class ComputeInstance implements Lifecycle, Metrizable {
    private String instanceId;
    private int cpuPercent;
    public ComputeInstance(String instanceId, int cpuPercent) {
        this.instanceId = instanceId;
        this.cpuPercent = cpuPercent;
    }
    @Override
    public void start() {
        System.out.println("Instance " + instanceId + " STARTED");
    }
    @Override
    public void stop() {
        System.out.println("Instance " + instanceId + " STOPPED");
    }
    @Override
    public int getCpuUsage() {
        return cpuPercent;
    }
}

public class CloudApp {
    public static void main(String[] args) {
        ComputeInstance instance = new ComputeInstance("i-0994bf", 42);
        instance.start();
        System.out.println("CPU: " + instance.getCpuUsage() + "%");
        instance.stop();
    }
}

