interface Printer {
    void printPage();
}

interface Scanner {
    void scanDocument();
}

class AllInOneCopier implements Printer, Scanner {
    @Override
    public void printPage() {
        System.out.println("Printing test page");
    }
    @Override
    public void scanDocument() {
        System.out.println("Scanning optical glass at 600 DPI");
    }
}

public class CopierApp {
    public static void main(String[] args) {
        Printer p = new AllInOneCopier();
        p.printPage();
        Scanner s = (Scanner) p;
        s.scanDocument();
    }
}

